-- THQ ERP v5.2 GST & Compliance
-- Migration 232: authoritative GST snapshot -> component journal-line mapper.
-- This migration does NOT post/replace any business journal. It only creates the canonical tax-line translation used by future v5.2 atomic posting endpoints.
begin;
update public.accounting_accounts set name=case system_key when 'rcm_input_gst' then 'RCM Input GST Pending / Receivable' when 'rcm_input_cgst' then 'RCM Input CGST Pending / Receivable' when 'rcm_input_sgst' then 'RCM Input SGST Pending / Receivable' when 'rcm_input_utgst' then 'RCM Input UTGST Pending / Receivable' when 'rcm_input_igst' then 'RCM Input IGST Pending / Receivable' when 'rcm_input_cess' then 'RCM Input Cess Pending / Receivable' else name end,description=case system_key when 'rcm_input_gst' then 'Control account for RCM input tax pending statutory payment and ITC eligibility; excluded from ordinary booked Input GST.' when 'rcm_input_cgst' then 'RCM CGST pending credit/control; reclassify only after RCM payment and ITC eligibility.' when 'rcm_input_sgst' then 'RCM SGST pending credit/control; reclassify only after RCM payment and ITC eligibility.' when 'rcm_input_utgst' then 'RCM UTGST pending credit/control; reclassify only after RCM payment and ITC eligibility.' when 'rcm_input_igst' then 'RCM IGST pending credit/control; reclassify only after RCM payment and ITC eligibility.' when 'rcm_input_cess' then 'RCM compensation cess pending credit/control; reclassify only after RCM payment and ITC eligibility.' else description end,updated_at=now() where system_key in('rcm_input_gst','rcm_input_cgst','rcm_input_sgst','rcm_input_utgst','rcm_input_igst','rcm_input_cess');
create or replace function private.gst_component_account_id_v520(p_tenant_id uuid,p_system_key text) returns uuid language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare v_id uuid;begin select a.id into v_id from public.accounting_account_mappings m join public.accounting_accounts a on a.id=m.account_id and a.tenant_id=m.tenant_id where m.tenant_id=p_tenant_id and m.mapping_key=p_system_key and a.system_key=p_system_key and a.active;if v_id is null then raise exception 'GST component accounting mapping % is missing or invalid',p_system_key;end if;return v_id;end $$;
revoke all on function private.gst_component_account_id_v520(uuid,text) from public,anon,authenticated;
create or replace function private.gst_tax_line_v520(p_tenant_id uuid,p_system_key text,p_amount numeric,p_side text,p_description text) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare v numeric:=round(coalesce(p_amount,0),2);v_side text:=lower(trim(coalesce(p_side,'')));begin if v<0 then raise exception 'GST journal component cannot be negative';end if;if v=0 then return null;end if;if v_side not in('debit','credit') then raise exception 'GST journal component side must be debit or credit';end if;return jsonb_build_object('account_id',private.gst_component_account_id_v520(p_tenant_id,p_system_key),'system_key',p_system_key,'debit',case when v_side='debit' then v else 0 end,'credit',case when v_side='credit' then v else 0 end,'description',p_description);end $$;
revoke all on function private.gst_tax_line_v520(uuid,text,numeric,text,text) from public,anon,authenticated;
create or replace function private.gst_snapshot_tax_journal_lines_v520(p_tenant_id uuid,p_snapshot_id uuid) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare s public.gst_document_snapshots_v520%rowtype;v jsonb:='[]'::jsonb;x jsonb;v_reverse boolean;v_input_side text;v_output_side text;v_rcm_input_side text;v_rcm_payable_side text;v_rcm_total numeric;begin select * into s from public.gst_document_snapshots_v520 where id=p_snapshot_id and tenant_id=p_tenant_id;if not found then raise exception 'Authoritative GST snapshot not found';end if;if s.source_type not in('sale','purchase','sales_return','purchase_return','purchase_invoice_v484') then raise exception 'GST journal mapper does not yet support source type %',s.source_type;end if;if s.document_kind='sale' and s.direction<>'outward' then raise exception 'GST snapshot direction/kind mismatch';end if;if s.document_kind='purchase' and s.direction<>'inward' then raise exception 'GST snapshot direction/kind mismatch';end if;v_reverse:=s.source_type in('sales_return','purchase_return');v_output_side:=case when v_reverse then 'debit' else 'credit' end;v_input_side:=case when v_reverse then 'credit' else 'debit' end;v_rcm_input_side:=case when v_reverse then 'credit' else 'debit' end;v_rcm_payable_side:=case when v_reverse then 'debit' else 'credit' end;if s.document_kind='sale' then x:=private.gst_tax_line_v520(p_tenant_id,'output_cgst',s.cgst_total,v_output_side,case when v_reverse then 'Sales return CGST reversal' else 'Output CGST' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'output_sgst',s.sgst_total,v_output_side,case when v_reverse then 'Sales return SGST reversal' else 'Output SGST' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'output_utgst',s.utgst_total,v_output_side,case when v_reverse then 'Sales return UTGST reversal' else 'Output UTGST' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'output_igst',s.igst_total,v_output_side,case when v_reverse then 'Sales return IGST reversal' else 'Output IGST' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'output_cess',s.cess_total,v_output_side,case when v_reverse then 'Sales return GST cess reversal' else 'Output GST compensation cess' end);if x is not null then v:=v||jsonb_build_array(x);end if;return v;end if;x:=private.gst_tax_line_v520(p_tenant_id,'input_cgst',s.cgst_total,v_input_side,case when v_reverse then 'Purchase return input CGST reversal' else 'Input CGST booked' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'input_sgst',s.sgst_total,v_input_side,case when v_reverse then 'Purchase return input SGST reversal' else 'Input SGST booked' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'input_utgst',s.utgst_total,v_input_side,case when v_reverse then 'Purchase return input UTGST reversal' else 'Input UTGST booked' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'input_igst',s.igst_total,v_input_side,case when v_reverse then 'Purchase return input IGST reversal' else 'Input IGST booked' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'input_cess',s.cess_total,v_input_side,case when v_reverse then 'Purchase return input cess reversal' else 'Input GST compensation cess booked' end);if x is not null then v:=v||jsonb_build_array(x);end if;v_rcm_total:=round(coalesce(s.rcm_cgst_total,0)+coalesce(s.rcm_sgst_total,0)+coalesce(s.rcm_utgst_total,0)+coalesce(s.rcm_igst_total,0)+coalesce(s.rcm_cess_total,0),2);if v_rcm_total>0 then x:=private.gst_tax_line_v520(p_tenant_id,'rcm_input_cgst',s.rcm_cgst_total,v_rcm_input_side,case when v_reverse then 'Purchase return RCM CGST pending-input reversal' else 'RCM CGST pending input' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'rcm_input_sgst',s.rcm_sgst_total,v_rcm_input_side,case when v_reverse then 'Purchase return RCM SGST pending-input reversal' else 'RCM SGST pending input' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'rcm_input_utgst',s.rcm_utgst_total,v_rcm_input_side,case when v_reverse then 'Purchase return RCM UTGST pending-input reversal' else 'RCM UTGST pending input' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'rcm_input_igst',s.rcm_igst_total,v_rcm_input_side,case when v_reverse then 'Purchase return RCM IGST pending-input reversal' else 'RCM IGST pending input' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'rcm_input_cess',s.rcm_cess_total,v_rcm_input_side,case when v_reverse then 'Purchase return RCM cess pending-input reversal' else 'RCM cess pending input' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'rcm_cgst_payable',s.rcm_cgst_total,v_rcm_payable_side,case when v_reverse then 'Purchase return RCM CGST payable reversal' else 'RCM CGST payable' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'rcm_sgst_payable',s.rcm_sgst_total,v_rcm_payable_side,case when v_reverse then 'Purchase return RCM SGST payable reversal' else 'RCM SGST payable' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'rcm_utgst_payable',s.rcm_utgst_total,v_rcm_payable_side,case when v_reverse then 'Purchase return RCM UTGST payable reversal' else 'RCM UTGST payable' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'rcm_igst_payable',s.rcm_igst_total,v_rcm_payable_side,case when v_reverse then 'Purchase return RCM IGST payable reversal' else 'RCM IGST payable' end);if x is not null then v:=v||jsonb_build_array(x);end if;x:=private.gst_tax_line_v520(p_tenant_id,'rcm_cess_payable',s.rcm_cess_total,v_rcm_payable_side,case when v_reverse then 'Purchase return RCM cess payable reversal' else 'RCM compensation cess payable' end);if x is not null then v:=v||jsonb_build_array(x);end if;end if;return v;end $$;
revoke all on function private.gst_snapshot_tax_journal_lines_v520(uuid,uuid) from public,anon,authenticated;
create or replace function private.gst_snapshot_tax_journal_lines_validate_v520(p_tenant_id uuid,p_snapshot_id uuid) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare s public.gst_document_snapshots_v520%rowtype;v jsonb;dr numeric;cr numeric;expected_collected numeric;expected_rcm numeric;begin select * into s from public.gst_document_snapshots_v520 where id=p_snapshot_id and tenant_id=p_tenant_id;if not found then raise exception 'Authoritative GST snapshot not found';end if;v:=private.gst_snapshot_tax_journal_lines_v520(p_tenant_id,p_snapshot_id);select coalesce(sum((x->>'debit')::numeric),0),coalesce(sum((x->>'credit')::numeric),0) into dr,cr from jsonb_array_elements(v)x;expected_collected:=round(coalesce(s.cgst_total,0)+coalesce(s.sgst_total,0)+coalesce(s.utgst_total,0)+coalesce(s.igst_total,0)+coalesce(s.cess_total,0),2);expected_rcm:=round(coalesce(s.rcm_cgst_total,0)+coalesce(s.rcm_sgst_total,0)+coalesce(s.rcm_utgst_total,0)+coalesce(s.rcm_igst_total,0)+coalesce(s.rcm_cess_total,0),2);if s.document_kind='sale' then if round(greatest(dr,cr),2)<>expected_collected then raise exception 'Outward GST journal component mapping does not match authoritative snapshot';end if;elsif s.document_kind='purchase' then if s.source_type in('purchase_return') then if round(cr,2)<>round(expected_collected+expected_rcm,2) or round(dr,2)<>expected_rcm then raise exception 'Inward return GST journal mapping does not match authoritative snapshot';end if;else if round(dr,2)<>round(expected_collected+expected_rcm,2) or round(cr,2)<>expected_rcm then raise exception 'Inward GST journal mapping does not match authoritative snapshot';end if;end if;end if;return jsonb_build_object('valid',true,'debit',round(dr,2),'credit',round(cr,2),'collected_tax',expected_collected,'rcm_tax',expected_rcm,'lines',v);end $$;
revoke all on function private.gst_snapshot_tax_journal_lines_validate_v520(uuid,uuid) from public,anon,authenticated;
insert into public.thq_schema_releases(migration_no,schema_version,release_name,notes) values(232,'5.2.0-foundation','GST Snapshot Journal Mapper','Adds the canonical authoritative-snapshot to GST component journal-line mapper. Outward collected GST maps to Output components; inward supplier GST maps to Input components; inward RCM maps to separate pending-input and RCM-payable components; outward recipient RCM never posts as THQ liability. No business journal is posted by this migration.') on conflict(migration_no) do update set schema_version=excluded.schema_version,release_name=excluded.release_name,notes=excluded.notes;
commit;